IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'e47eb440-16b8-4df9-8862-049cdbe24274')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'e47eb440-16b8-4df9-8862-049cdbe24274', N'f77ee04a-e3d6-4973-b100-f3810817cbad', N'Technology', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>Integrated logistics solutions for a changing world</strong></h2><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791983802851","type":"Section","label":"About","title":"Technology","subtitle":"","items":[{"id":"legacy-text-1791983802851","type":"CardText","text":"<h2><strong>Getting your products to market on time can be the difference between success and failure in an environment where product life cycles can be over in a matter of months.</strong></h2><h2><strong>We''ve been part of the technology revolution for more than 30 years with supply chain solutions that are innovative, flexible and tailor made for the industry. We cover the entire supply chain from multi-tier fulfilment and merge-in-transit to white glove deliveries and after sales services.</strong></h2><h2><strong>Our proven expertise in this disruptive, fast-moving market enables us to work together with you to build solutions that harness our sector-tuned IT systems and provide you with the e-services and near-real-time visibility you need. What’s more our state-of-the-art IT systems can be fully integrated with your systems</strong></h2><p></p>"}]},{"id":"section-1791983868650-205ajd","type":"Section","label":"","title":"Computing and enterprise data centres","subtitle":"","items":[{"id":"text-1791983868650-am7sxo","type":"CardText","text":"<h2><strong>Our solutions give original design manufacturers (ODM) and original equipment manufacturers (OEM) control of the entire supply chain, from contract manufacturer to on-site installation at the end customer.</strong></h2><h2><strong>As equipment manufacturing now takes place in different parts of the world, supply chain management is becoming the core competency, replacing production management.</strong></h2><h2><strong>OEMs are moving beyond disconnected products and services into original solution orchestrators (OSOs), which dramatically increases the need for end-to-end process design, change management, analytics and project management skill sets within high-tech supply chain organisations.</strong></h2><h2><strong>Our data processing and storage solutions give you the necessary visibility and reliability to maintain full end-to-end control.</strong></h2><p></p>"}]},{"id":"section-1791983868834-fr08hv","type":"Section","label":"","title":"Telecommunication and network equipment","subtitle":"","items":[{"id":"text-1791983868834-q8lhxe","type":"CardText","text":"<h2><strong>We provide manufacturers of voice and data infrastructure with agile logistics solutions for component and spare part warehousing and finished product distribution, including complete order fulfilment and postponement. We can also operate your after sales service centres.</strong></h2><h2><strong>Our innovative cross-dock and merge-in-transit solutions are always aligned with your ever changing demands and the stringent quality and safety standards of our TEM and NEP customers.</strong></h2><h2><strong>With our one-stop-shop solution, we unite the dense DS road freight network and TAPA-A regional distribution centres with strategic third party partnerships to offer niche services like in-night delivery services and white glove deliveries.</strong></h2><h2><strong>Given the high value and short life cycles of products coming from telecommunication equipment manufacturers (TEM) and network equipment providers (NEP), our supply chain deliverable is to combine or merge the various providers of commercial, off the shelf components to the telecommunications and network equipment industry into a finished product just before delivery to the end customer.</strong></h2><p></p>"}]},{"id":"section-1791983869018-gukmh1","type":"Section","label":"","title":"Consumer electronics","subtitle":"","items":[{"id":"text-1791983869018-8v9qyu","type":"CardText","text":"<h2><strong>Our supply chain solutions are critically important to your reducing product life cycles. Between 50% and 70% of consumers buy an alternative product or leave a store empty handed when their first product choice is out of stock. This shows how important supply chain efficiency is for brand satisfaction and profit maximisation.</strong></h2><h2><strong>We facilitate new product launches and offer after sales support, while our global network guarantees inbound freight capacity at scheduled lines.</strong></h2><h2><strong>Our specialised TAPA-A Distribution Centres offer you agility and critical economies of scale, and our distribution network ensures timely delivery, whether to a large retail chain’s DC or to a consumer’s home.</strong></h2><h2><strong>Additionally, as part of our commitment to the UN Global Compact initiative, we proactively advise you on carbon footprint reduction.</strong></h2><p></p>"}]},{"id":"section-1791983869186-zlq3hy","type":"Section","label":"","title":"Reprographic equipment","subtitle":"","items":[{"id":"text-1791983869186-ak8bb6","type":"CardText","text":"<h2><strong>Supply chains in the reprographic industry are consolidating to Remote Data Capture (RDC) and Electronic Data Capture (EDC) as digitalisation has slashed demand for traditional black-and-white and colour printing in developed markets.</strong></h2><h2><strong>We have a long history serving the printing and copying equipment market and offer you light manufacturing and configuration of finished products, installation services upon delivery, repair/return services and spare part distribution.</strong></h2><h2><strong>Our variable cost base allows easy up and downscaling so you can adapt your supply chains to match changing market conditions.</strong></h2><p></p>"}]},{"id":"section-1791983869418-yqw9iu","type":"Section","label":"","title":"Service differentiation and excellence in e-commerce","subtitle":"","items":[{"id":"text-1791983869418-k1zpfe","type":"CardText","text":"<h2><strong>We integrate our IT platform into your e-commerce platform, offering visibility into inventory, order status and track and trace data - and giving you greater channel mobility, increased personalisation and more delivery models.</strong></h2><h2><strong>More than 50% of computers are sold online, and emerging opportunities such as m-commerce (mobiles/smartphones) and s-commerce (social media) are growing fast. Meeting logistics requirements plays an important role in increasing retention rates.</strong></h2><p></p>"}]},{"id":"section-1791983869610-qwc7uo","type":"Section","label":"The back-end","title":"Will you tailor storage and picking solutions to meet my needs?","subtitle":"","items":[{"id":"text-1791983869610-f8akdo","type":"CardText","text":"<h2><strong>Yes, whether you need storage in bulk, on shelves, in racks or in temperature-controlled environments, we will tailor a solution to your needs. You can also choose from a wide variety of picking principles, including ''First Expired, First Out'' (FEFO), ‘Last In First Out’ (LIFO) and ''First In, First Out'' (FIFO).</strong></h2><p></p>"}]},{"id":"section-1791983869834-r14s1w","type":"Section","label":"","title":"What do you offer apart from core technology logistics services?","subtitle":"","items":[{"id":"text-1791983869834-uypuzp","type":"CardText","text":"<h2><strong>Value-added services, which will be tailored to your needs, include: kitting/assembly, testing, configuration/customisation, repairs, quality inspection, and customs clearance procedures and fiscal representation.</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'fa23feb4-469e-4857-9305-0ebb7e20f01f')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'fa23feb4-469e-4857-9305-0ebb7e20f01f', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Road Transportation', 2, NULL, NULL, NULL, NULL, NULL, N'<h3>Local, national and international distances</h3><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791978986193","type":"Section","label":"About","title":"Road Transportation","subtitle":"","items":[{"id":"legacy-text-1791978986193","type":"CardText","text":"<h2>Whether you have a single shipment, a few pallets or multiple full loads every week, we can handle your cargo and give you the best solution for your road freight needs.</h2><h2>With traffic hubs located all over the world, we make sure your cargo is delivered safely and efficiently wherever it needs to go.&nbsp;</h2><p></p>"}]},{"id":"page-highlights-highlight-1791979096725-9dz2il","type":"PageHighlights","items":[{"id":"highlight-1791979096725-9dz2il","type":"HighlightText","text":"<h2>We offer road transport services for:</h2><ul><li><p><strong>Full load shipments</strong></p></li><li><p><strong>Part load shipments</strong></p></li><li><p><strong>Groupage shipments</strong></p></li></ul><p></p>"}]},{"id":"page-closings-closing-1791979121703-khmijg","type":"PageClosings","items":[{"id":"closing-1791979121703-khmijg","type":"ClosingText","text":"<h3><strong>Domestic shipments and shipments to neighbouring countries can be completed within 24-48 hours. For more remote or exotic destinations in Europe we offer delivery within one to five days at all destinations.</strong></h3><p></p>"}]},{"id":"section-1791979153201-y4zu1a","type":"Section","label":"","title":"LOCAL KNOWLEDGE AND LOCAL PRESENCE","subtitle":"","items":[{"id":"text-1791979153201-08mq0h","type":"CardText","text":"<h2><strong>All of our offices are staffed by experienced freight forwarders and sales staff who know your market and local transport conditions. Whether you need one pallet transported or multiple shipments each day, we can make sure you get the&nbsp;transport solution that matches your needs exactly.</strong></h2><h2></h2><p></p>"}]},{"id":"section-1791979154252-thano6","type":"Section","label":"","title":"CONTROL TOWERS FOR YOUR GLOBAL SETUP","subtitle":"","items":[{"id":"text-1791979154252-9ctv58","type":"CardText","text":"<h2><strong>If you have a global setup and require visibility in your supply chain, we can set up control towers for your company.&nbsp;As one of the leading transport and logistics providers, we help you maintain control so you can benefit from reduced inventory, improved on-time delivery and logistics costs savings. Everything is handled by your single point of contact at our Global Accounts department.</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'c97a48ac-10a1-4e3b-a9cf-0fbec69f985c')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'c97a48ac-10a1-4e3b-a9cf-0fbec69f985c', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'From Egypt to China', 3, N'<p><strong>Together, ILS Egypt and Millennium FBA are creating seamless logistics solutions that connect markets, strengthen trade, and drive global growth.</strong></p>', N'/uploads/content/8578c6ba9553480cb53b9f03b0768b24.webp', NULL, N'Ils News', CAST(N'2025-12-29T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'de9484b9-a538-4659-8cfb-1409ecdf03e6')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'de9484b9-a538-4659-8cfb-1409ecdf03e6', N'f77ee04a-e3d6-4973-b100-f3810817cbad', N'Automotive Logistics', 2, NULL, NULL, NULL, NULL, NULL, N'<h2>Driving the world’s automotive supply chains for over 30 years</h2><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791982859290","type":"Section","label":"","title":"Service offerings the way you need them","subtitle":"","items":[{"id":"legacy-text-1791982859290","type":"CardText","text":"<h2><strong>Bespoke, standardised, stand alone or integrated</strong></h2><p></p>"}]},{"id":"section-1791983076522-0jg26k","type":"Section","label":"(EMC2)","title":"Electrification & Mobility Competence Center ","subtitle":"","items":[{"id":"text-1791983076522-nwuyvh","type":"CardText","text":"<h2><strong>ILS’s Electrification and Mobility Competence Center EMC2 Support to create sustainable supply chains using our expertise with future mobility platforms, high energy lithium batteries and dangerous rated automotive goods</strong></h2><p></p>"}]},{"id":"section-1791983107754-7bjq6n","type":"Section","label":"","title":"3PL & 4PL","subtitle":"","items":[{"id":"text-1791983107754-iwkbrj","type":"CardText","text":"<h2><strong>3PL &amp; 4PL offerings Includes physical and digital operational control towers powered with ILS’s IT and TMS systems and tools for full track and traceability of your cargo that can be seamlessly integrated into ERP system.</strong></h2><p></p>"}]},{"id":"section-1791983108122-jhgbfb","type":"Section","label":"(VCC)","title":"Finished Vehicle Competency Center ","subtitle":"","items":[{"id":"text-1791983108122-d0hfdl","type":"CardText","text":"<h2><strong>ILS provides Finished Vehicle transportation solutions for low volume high value production vehicles, test vehicles, exotics, concept, and show vehicles through our Vehicle Competency Center.</strong></h2><p></p>"}]},{"id":"section-1791983165490-dz10fc","type":"Section","label":"","title":"Automotive afterparts and service operations","subtitle":"","items":[{"id":"text-1791983165490-g50fuc","type":"CardText","text":"<h2><strong>A full suite of post part and vehicle manufacturing services including import and export Distribution Centers and dealer services (depending on geography).</strong></h2><p></p>"}]},{"id":"section-1791983165802-835j0n","type":"Section","label":"","title":"Inbound","subtitle":"","items":[{"id":"text-1791983165802-7524rg","type":"CardText","text":"<h2><strong>Inbound to manufacturing planning, transportation, and optimisation.</strong></h2><p></p>"}]},{"id":"section-1791983166114-f8z1zk","type":"Section","label":"","title":"Warehousing & value added solutions","subtitle":"","items":[{"id":"text-1791983166114-9ugter","type":"CardText","text":"<h2><strong>ILS has vast capability and experience in warehousing, value added solutions, packaging, vendor managed inventory, JIT, kitting, sequencing and other line side delivery and assembly services.</strong></h2><p></p>"}]},{"id":"section-1791983215659-mygmh6","type":"Section","label":"","title":"Our experts are the strongest link in your supply chain","subtitle":"","items":[{"id":"text-1791983215659-zev9k7","type":"CardText","text":"<h2><strong>ILS’s Automotive Subject Matter Experts are critical thinkers that can be the differentiator you need to keep the manufacturing process running efficiently and end users’ vehicles on the road. Our global team know how the automotive industry gears turn and use their knowledge and experience to design processes and flows that match automotive development and production milestones.</strong></h2><p></p>"}]}]}');

