IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'e4b6395b-c99f-44ca-b5c6-5cf8670bbe2a')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'e4b6395b-c99f-44ca-b5c6-5cf8670bbe2a', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Air Freight', 2, NULL, NULL, NULL, NULL, NULL, N'<h3>When you need it fast, you need air freight</h3><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791980080665","type":"Section","label":"With daily worldwide departures, you can rely on ILS''s air freight services","title":"ILS Air Freight","subtitle":"","items":[{"id":"legacy-text-1791980080665","type":"CardText","text":"<h2><strong>With daily worldwide departures, you can rely on ILS''s air freight services</strong></h2><h2><strong>ILS''s air freight services are a reliable option for air freight of all sizes and types. Whether you’re shipping perishables, hazardous cargo or any commodity that needs fast delivery, ILS can provide the solution that meets your needs.</strong></h2><p></p>"}]},{"id":"section-1791980158713-g1j1ys","type":"Section","label":"","title":"DELIVERY TO YOUR DOORSTEP","subtitle":"","items":[{"id":"text-1791980158713-7qr6ol","type":"CardText","text":"<h2><strong>As a global air freight forwarder, our network stretches around the world keeping your cargo within the ILS network throughout its journey from door-to-door.</strong></h2><p></p>"},{"id":"highlight-1791980318049-oxbv02","type":"HighlightText","text":"<h2><strong><br> Our services include:</strong></h2><ul><li><p><strong>Full charter air freight</strong></p></li><li><p><strong>Part charter air freight</strong></p></li><li><p><strong>On-board courier</strong></p></li><li><p><strong>Consolidation</strong></p></li><li><p><strong>Back-to-back</strong></p></li><li><p><strong>ILS Express - our courier service</strong></p></li></ul><p></p>"},{"id":"closing-1791980497498-gpfs4g","type":"ClosingText","text":"<h2><strong>NO MATTER THE SIZE, TYPE AND FREQUENCY OF YOUR CARGO, ILS HAVE A SERVICE THAT FITS YOUR NEEDS. </strong></h2><p></p>"}]},{"id":"section-1791980544178-zm28as","type":"Section","label":"","title":"AIR FREIGHT COMPLIANCE AND DOCUMENTATION SUPPORT","subtitle":"","items":[{"id":"text-1791980544178-rvw9ks","type":"CardText","text":"<h2><strong>ILS''s air freight team is&nbsp;always up to date with the latest requirements in air freight compliance. With first-hand knowledge of local conditions, rules and regulations, ILS can handle all administrative and documentation procedures and ensure the smooth handling of your air cargo – wherever in the world it may be. This includes customs clearance, security, license requirements and compliance with other local regulations.&nbsp;</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'55bdbcf5-ba02-4847-8b56-5d86b3cb95f9')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'55bdbcf5-ba02-4847-8b56-5d86b3cb95f9', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'Breakbulk Shipment of Industrial Machinery', 3, N'<p><code>We successfully shipped, cleared, and transported a 186-ton Breakbulk shipment with unmatched precision and seamless coordination.</code></p>', N'/uploads/content/52ad9e13aaaf4d049e7562d91b5de9ad.webp', NULL, N'Case Study', CAST(N'2025-12-29T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'12743fb3-1eea-4e0c-bbab-61bb3cadfc1e')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'12743fb3-1eea-4e0c-bbab-61bb3cadfc1e', N'cc99c0e8-2139-4d75-9a51-25623a5799e6', N'ILS Values', 2, NULL, NULL, NULL, NULL, NULL, N'<p><strong>Our culture and our services are defined by our global values </strong></p><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791978492720","type":"Section","label":"","title":"Wherever you meet us, we are driven by the same beliefs","subtitle":"","items":[{"id":"legacy-text-1791978492720","type":"CardText","text":"<p></p><p></p><p></p>"},{"id":"highlight-1792002180380-yy8u11","type":"HighlightText","text":"<p></p><h2><strong>Customers first</strong></h2><ul><li><p>We deliver great customer experiences and high quality services</p></li><li><p>We are proactive in our customer dealings and work hard to retain customers</p></li><li><p>We make it easy for our customers to do business with us</p></li></ul><p></p>"},{"id":"highlight-1792002202643-4977e9","type":"HighlightText","text":"<p></p><h2><strong>Best performance</strong></h2><ul><li><p>We are transparent and driven by results</p></li><li><p>We work together as ONE ILS across our entire global network</p></li><li><p>We are driven by entrepreneurship and local empowerment</p></li></ul><p></p>"},{"id":"highlight-1792002214379-vei6fk","type":"HighlightText","text":"<h2><strong>True collaboration</strong></h2><ul><li><p>We take ownership and show initiative</p></li><li><p>We collaborate and communicate in a respectful way</p></li><li><p>We practice open dialogue</p></li></ul><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'fcda0290-45fa-4985-a5ca-62dde640b43f')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'fcda0290-45fa-4985-a5ca-62dde640b43f', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'Welcome Aboard', 3, N'<p><strong>We are thrilled to announce two new distinguished members joining our team at ILS Egypt.</strong></p><p>we are welcoming Mr. Mohamed Al Amrousy, who will be taking on the role of Commercial Manager, and Mr. Mohamed Al shabassy, who will be stepping into the position of Business Development Manager.</p><p>We are excited about the dynamic future ahead and look forward to the contributions both Mr. Mohamed Al Amrousy and Mr. Mohamed Al shabassy will bring to our company.</p>', N'/uploads/content/2a17f99b887043938226d477aa12b484.webp', NULL, N'Ils News', CAST(N'2025-11-21T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'5ebac76b-6d11-4475-afcf-6dcfbb6c2d35')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'5ebac76b-6d11-4475-afcf-6dcfbb6c2d35', N'3e0c0a0a-3471-4787-b956-7653fb76de7f', N'Container Types', 2, NULL, NULL, NULL, NULL, NULL, NULL, N'{"version":1,"items":[{"id":"page-highlights-highlight-1791986090124-d836oh","type":"PageHighlights","items":[{"id":"highlight-1791986090124-d836oh","type":"HighlightText","text":"<h2><strong>Shipping containers come in different designs and sizes to suit different types of cargo. The right container depends on the nature of the goods, their dimensions, weight, volume, loading method and any special handling requirements.</strong></h2><p></p>"}]},{"id":"legacy-section-1791985484932","type":"Section","label":"","title":"The most common types of shipping containers are:","subtitle":"","items":[{"id":"highlight-1791986075188-8mj58e","type":"HighlightText","text":"<h2>1. General Purpose Container (Dry Container)</h2><h3><em>General purpose containers are the standard choice for most dry cargo and are suitable for goods that do not require temperature control or special loading arrangements.</em></h3><p>Common sizes include:</p><ul><li><p>20GP — 20'' General Purpose Container</p></li></ul><ol><li><p>Volume: 33 m³</p></li><li><p>Net Weight: 21,640 kg</p></li><li><p>Inside Length: 5.90 m</p></li><li><p>Inside Width: 2.35 m</p></li><li><p>Inside Height: 2.39 m</p></li><li><p>Door Opening: 2.28 × 2.34 m</p></li></ol><ul><li><p>40GP — 40'' General Purpose Container</p></li></ul><ol><li><p>Volume: 67 m³</p></li><li><p>Net Weight: 26,500 kg</p></li><li><p>Inside Length: 12.00 m</p></li><li><p>Inside Width: 2.35 m</p></li><li><p>Inside Height: 2.39 m</p></li><li><p>Door Opening: 2.28 × 2.34 m</p></li></ol><h2></h2><p></p>"},{"id":"highlight-1791986012277-cuvy26","type":"HighlightText","text":"<h2>2. Flat Rack Container</h2><h3><em>Flat rack containers are designed for heavy, oversized or irregularly shaped cargo that cannot be loaded into a standard enclosed container.</em></h3><ul><li><p>20Flat — 20'' Flat Rack</p></li></ul><ol><li><p>Net Weight: 21,470 kg</p></li><li><p>Inside Length: 5.62 m</p></li><li><p>Inside Width: 2.20 m</p></li><li><p>Inside Height: 2.23 m</p></li></ol><ul><li><p>40Flat — 40'' Flat Rack</p></li></ul><ol><li><p>Net Weight: 39,000 kg</p></li><li><p>Inside Length: 12.00 m</p></li><li><p>Inside Width: 2.43 m</p></li><li><p>Inside Height: 2.10 m</p></li></ol><h2></h2><p></p>"},{"id":"highlight-1791986132445-3zkt5w","type":"HighlightText","text":"<h2>3. Open Top Container</h2><h3><em>Open top containers are suitable for cargo that is too tall or difficult to load through standard container doors. Cargo can be loaded from the top when required.</em></h3><ul><li><p>20Open — 20'' Open-Top Container</p></li></ul><ol><li><p>Volume: 32.6 m³</p></li><li><p>Net Weight: 21,700 kg</p></li><li><p>Inside Length: 5.88 m</p></li><li><p>Inside Width: 2.33 m</p></li><li><p>Inside Height: 2.31 m</p></li><li><p>Door Opening: 2.28 × 2.33 m</p></li></ol><ul><li><p>40Open — 40'' Open-Top Container</p></li></ul><ol><li><p>Volume: 66.7 m³</p></li><li><p>Net Weight: 26,530 kg</p></li><li><p>Inside Length: 12.01 m</p></li><li><p>Inside Width: 2.33 m</p></li><li><p>Inside Height: 2.31 m</p></li><li><p>Door Opening: 2.28 × 2.33 m</p></li></ol><h2></h2><p></p>"},{"id":"highlight-1791986132653-gin5w7","type":"HighlightText","text":"<h2>4. Double Door Container</h2><h3><em>Double door containers have doors at both ends, making loading and unloading easier when access from both sides is required.</em></h3><p></p>"},{"id":"highlight-1791986132884-lse3x5","type":"HighlightText","text":"<h2>5. High Cube Container</h2><h3><em>High cube containers provide additional internal height compared with standard containers and are suitable when extra vertical capacity is required.</em></h3><ul><li><p>40HC — 40'' High Cube Container</p></li></ul><ol><li><p>Volume: 76 m³</p></li><li><p>Net Weight: 26,330 kg</p></li><li><p>Inside Length: 12.00 m</p></li><li><p>Inside Width: 2.35 m</p></li><li><p>Inside Height: 2.69 m</p></li><li><p>Door Opening: 2.58 × 2.33 m</p></li></ol><h2></h2><h2></h2><p></p>"},{"id":"highlight-1791986133125-383n3h","type":"HighlightText","text":"<h2>6. Open Side Container</h2><h2><em>Open side containers provide wider side access and are useful for cargo that is difficult to load through standard end doors.</em></h2><h2></h2><p></p>"},{"id":"highlight-1791986133421-rlag60","type":"HighlightText","text":"<h2>7. ISO Reefer Container</h2><h3><em>Refrigerated containers are designed for temperature-sensitive cargo requiring controlled transport conditions.</em></h3><ol><li><p>20Reefer — 20'' Refrigerated Container</p></li><li><p>Volume: 28 m³</p></li><li><p>Net Weight: 20,770 kg</p></li><li><p>Inside Length: 5.48 m</p></li><li><p>Inside Width: 2.25 m</p></li><li><p>Inside Height: 2.26 m</p></li><li><p>Door Opening: 2.22 × 2.23 m</p></li></ol><ul><li><p>40Reefer — 40'' Refrigerated Container</p></li></ul><ol><li><p>Volume: 57 m³</p></li><li><p>Net Weight: 25,500 kg</p></li><li><p>Inside Length: 11.48 m</p></li><li><p>Inside Width: 2.26 m</p></li><li><p>Inside Height: 2.18 m</p></li><li><p>Door Opening: 2.13 × 2.26 m</p></li></ol><h2></h2><p></p>"},{"id":"highlight-1791986133685-lewqz5","type":"HighlightText","text":"<h2>8. Insulated Container</h2><h3><em>Insulated containers are designed to help protect cargo from external temperature changes and are suitable for goods requiring additional thermal protection.</em></h3><h2></h2><p></p>"},{"id":"highlight-1791986134636-34fxey","type":"HighlightText","text":"<h2>9. Half-Height Container</h2><h3><em>Half-height containers are designed for dense and heavy cargo where a lower container height is more suitable for loading and handling.</em></h3><h2></h2><p></p>"},{"id":"highlight-1791986208772-hglzyr","type":"HighlightText","text":"<h2>10. ISO Tank Container</h2><h3><em>ISO tank containers are designed for transporting liquids and other bulk cargo in a secure containerised format.</em></h3><h2></h2><p></p>"},{"id":"highlight-1791986208917-0xqgqr","type":"HighlightText","text":"<h2>11. Swap Body Container</h2><h3><em>Swap bodies are designed for flexible intermodal transport and can be transferred between different transport modes as part of an integrated logistics solution.</em></h3><p></p>"},{"id":"legacy-text-1791985484932","type":"CardText","text":"<h2><strong>Choosing the Right Container</strong></h2><h3><em>Selecting the right container depends on the type of cargo, its dimensions, weight, volume, loading requirements and transport conditions.</em></h3><p></p>"},{"id":"closing-1791986232869-yn9lzb","type":"ClosingText","text":"<h2><strong><em>For standard dry cargo, General Purpose containers are usually the most suitable option. For oversized or heavy cargo, Flat Rack or Open Top containers may be more appropriate. Temperature-sensitive goods may require an ISO Reefer container, while specialised cargo may require Open Side, Tank or other specialised container solutions.</em></strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'26e73cba-e82c-466d-a7e6-84a70496c8ab')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'26e73cba-e82c-466d-a7e6-84a70496c8ab', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Customs Clearance', 2, NULL, NULL, NULL, NULL, NULL, N'<p>Our licensed broker services ensure compliance</p>', N'{"version":1,"items":[{"id":"legacy-section-1791980599883","type":"Section","label":"THE EXPERTISE YOU NEED TO ENSURE","title":" SUCCESSFUL TRANSPORT AND DELIVERY","subtitle":"","items":[{"id":"legacy-text-1791980599883","type":"CardText","text":"<h2><strong>In a global economy, customs clearance is a complex and ever changing landscape of rules, regulations, and paperwork. Let our experts manage your customs clearance, saving you time and ensuring successful transport and delivery.</strong></h2><p></p>"},{"id":"highlight-1791981322258-jeauqa","type":"HighlightText","text":"<h3><strong>In most countries with ILS offices, we are licensed customs brokers. And in other countries we have arrangements with agents.</strong></h3><p></p>"},{"id":"text-1791981345218-n1rj05","type":"CardText","text":"<h2><strong>Regardless of the precise local setup, our highly experienced experts can help you handle all your customs needs - from import and export declarations, temporary importation and customs warehousing to duty drawbacks and national customs rulings.</strong></h2><h2><strong>Our customs brokers have expertise in local conditions, regulatory requirements, tariff updates, and more. With this knowledge, we can process your custom clearances with accuracy and efficiency.</strong></h2><p></p>"}]},{"id":"section-1791981375466-xklaq4","type":"Section","label":"","title":"CUSTOMS CARE AND COMPLIANCE","subtitle":"","items":[{"id":"text-1791981375466-4vfdcn","type":"CardText","text":"<h2><strong>At ILS, we understand the importance of properly handled customs formalities and compliance with all laws and regulations governing the importation and exportation of goods. Our comprehensive local and global customs compliance programmer ensures that your customs documentation is accurate and compliant.&nbsp;</strong></h2><h3>Depending on the country, we can offer advice, special customs entries and procedures including:</h3><ul><li><p><strong>Import and export declarations</strong></p></li><li><p><strong>Temporary importation</strong></p></li><li><p><strong>Weekly groupage services from Alexandria to Port Said</strong></p></li><li><p><strong>Customs warehousing</strong></p></li><li><p><strong>Duty drawback</strong></p></li><li><p><strong>National customs rulings</strong></p></li></ul><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'fb939db8-154f-458c-a09b-908cbbbc3061')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'fb939db8-154f-458c-a09b-908cbbbc3061', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'Red Sea Container Terminal No. 1 in Ain Sokhna Port Begins Trial Operations', 3, N'<p><code>Egypt’s Red Sea Container Terminal No. 1 at Ain Sokhna Port has received its first vessel and begun trial operations, marking a key step in Egypt’s push to expand port capacity and position itself as a regional logistics hub.</code></p>', N'/uploads/content/1558fe11c93a41b09831da0e19139bdd.jpg', NULL, N'Industry News', CAST(N'2026-12-15T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'57432f9d-2df9-424f-a733-a041c99f6151')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'57432f9d-2df9-424f-a733-a041c99f6151', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Consolidations', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>When it''s urgent and you need something delivered fast</strong></h2><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791981548619","type":"Section","label":"","title":"ILS - The Professionals in LCL","subtitle":"","items":[{"id":"legacy-text-1791981548619","type":"CardText","text":"<h2><strong>As one of the most reliable consolidator ILS offers an excellent, unique and cost-effective LCL (less than container-load) service to all main ports in the world using the ports of Alexandria, Port Said , Cairo as receiving terminals ( Gateways).</strong></h2><h2><strong>ILS is the best alternative in the consolidation business.</strong></h2><h2><strong>The working procedures are according to the latest quality standards in our industry, using their own modern C.F.S. (container freight station) for handling all our Import and Export groupage cargo.</strong></h2><p></p>"},{"id":"highlight-1791981641210-33o5f5","type":"HighlightText","text":"<h3><strong>Having a unique system of hubs and networks of agents through the whole world from main ports to inland destinations, results in a weekly service to /from 400 destinations ! A unique one stop shopping concept saving our clients time and costs.</strong></h3><p></p>"}]},{"id":"section-1791981675034-wextzm","type":"Section","label":"","title":"LCL SERVICES INCLUDE:","subtitle":"","items":[{"id":"text-1791981675034-xxnqv0","type":"CardText","text":"<ul><li><p><strong>Weekly direct Import Consolidation services from over than 400 global destinations</strong></p></li><li><p><strong>Weekly Export services to more than 400 destinations direct and via various Hubs in Europe, Asia, Middle East and North and South USA</strong></p></li><li><p><strong>Weekly groupage services from Alexandria to Port Said</strong></p></li><li><p><strong>Daily LTL services to the main Cities in Egypt (Cairo – Suez – Damietta – Sokhna.etc.)</strong></p></li><li><p><strong>Stuffing and de-stuffing</strong></p></li><li><p><strong>Modern CFS Services</strong></p></li><li><p><strong>Bonded and Non bonded Warehousing</strong></p></li><li><p><strong>Distributions</strong></p></li><li><p><strong>Packing and removals</strong></p></li><li><p><strong>Customs clearance</strong></p></li></ul><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'99712614-d00e-4b31-8410-a3c414f1de5a')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'99712614-d00e-4b31-8410-a3c414f1de5a', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'ILSegypt cooperate #Midea for opening one of its factories at Sadat City', 3, N'<p>وضع المهندس أحمد سمير، وزير التجارة والصناعة، اليوم، حجر الأساس لمصنع جديد لشركة ميديا إليكتريك مصر الصينية المتخصصة في إنتاج الأجهزة المنزلية بالمنطقة الصناعية بمدينة السادات،ووالذى يقام على مساحة 220 ألف متر مربع، وذلك بحضور السفير/ لياو ليتشيانج سفير الصين بالقاهرة والدكتور/ أحمد كُريم نائب رئيس الهيئة العامة للاستثمار لشئون ترويج الاستثمار، والسيد/عمرو سعيد الرئيس التنفيذي لشركة ميديا إليكتريك مصر.</p><p><br></p>', N'/uploads/content/fc3e07d947f647839670edf31a07847c.webp', NULL, N'Ils News', CAST(N'2025-11-23T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'c23c53e4-c0d0-4ec4-a197-a55a2d2b9f89')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'c23c53e4-c0d0-4ec4-a197-a55a2d2b9f89', N'f77ee04a-e3d6-4973-b100-f3810817cbad', N'Healthcare Logistics', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>Logistics that make the world a better place</strong></h2><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791983372786","type":"Section","label":"About","title":"Healthcare Logistics","subtitle":"","items":[{"id":"legacy-text-1791983372786","type":"CardText","text":"<h2><strong>Rising costs from research and development, complex supply chains and stringent regulations are just a few of the challenges you need to overcome when working with healthcare transport and logistics.</strong></h2><p></p>"}]},{"id":"section-1791983461794-g26nw5","type":"Section","label":"","title":"We can help you make a difference","subtitle":"","items":[{"id":"text-1791983461794-jqgvia","type":"CardText","text":"<h2><strong>Our services, facilities and transport networks comply with all relevant healthcare quality standards and regulations. Furthermore, our tailor-made, integrated supply chain solutions cover everything from transport to storage as well as cold chain services.</strong></h2><p></p>"}]},{"id":"section-1791983543986-rivzgc","type":"Section","label":"Biopharma","title":"Specialist healthcare solutions","subtitle":"","items":[{"id":"text-1791983543986-fjaka5","type":"CardText","text":"<h2><strong>Our innovative supply chain and transport solutions support your business to get your products where they need to be.</strong></h2><h2><strong>Our GMP and GDP warehouse and distribution services include FEFO picking, clinical trial management, repacking and display configuration, all controlled by our in-house pharmacists.</strong></h2><h2><strong>Delivery services eliminate costs and inefficiencies, and include next-day delivery, direct-to-hospital department deliveries, 24/7 standby service and recall management – all available in condition-controlled environments.</strong></h2><h2><strong>We work with biologicals, pharmaceutical products (prescription drugs, generics, controlled drugs and over-the-counter (OTC) products), vaccines, active pharmaceutical ingredients (APIs) and clinical trial materials.</strong></h2><p></p>"}]},{"id":"section-1791983544282-c6t1ng","type":"Section","label":"","title":"Medical devices and diagnostics","subtitle":"","items":[{"id":"text-1791983544282-qr88o1","type":"CardText","text":"<h2><strong>We have been providing tailored supply chain solutions and healthcare logistics services to the medical devices and diagnostics market for more than 20 years.</strong></h2><h2><strong>Our services include orthopaedic loaner kit management, consignment stock management, preparation of procedure-based trolleys, sterile picking, clean rooms, technical repair and rework centres, 24/7 standby service, in-hospital replenishments, white-glove deliveries and spare parts management.</strong></h2><h2><strong>Our broad base of medical device customers comprises all classes of devices (I, IIa, IIb, III).</strong></h2><p></p>"}]},{"id":"section-1791983544538-m9srn0","type":"Section","label":"","title":"Medical products and personal care","subtitle":"","items":[{"id":"text-1791983544538-rtn9hs","type":"CardText","text":"<h2><strong>ILS is experienced in creating lean, flexible supply chain and transport solutions for many different destinations: from pharmacies to retail outlets, as well as direct to patients. We operate dedicated and multi-user warehouse operations and manage regional distribution centres with ‘control towers’, some of which manage over 1,000 shipments a day. Our services include packaging and repackaging, labelling and kitting (before shipping the goods for final delivery to the hospital ward where products are replenished by ILS), managing waste, returns and stock levels, restacking based on expiration date, and swapping products.</strong></h2><p></p>"}]},{"id":"section-1791983544770-2fkfmc","type":"Section","label":"","title":"Hospitals and care homes","subtitle":"","items":[{"id":"text-1791983544770-jipqsi","type":"CardText","text":"<h2><strong>Our efficient supply chain solutions improve visibility and reduce costs, which helps improve patient care in hospitals, clinics, and nursing homes. Our services include direct delivery to hospital wards, sterile goods logistics, drug management, operational procurement, laboratory logistics management of medical goods, disposal of hazardous waste, stock reduction programmes, inventory management, warehousing, external and internal distribution, eplenishment at ward level and much more.</strong></h2><p></p>"}]},{"id":"section-1791983544994-hpq4ng","type":"Section","label":"","title":"Can you deliver my products to diverse locations?","subtitle":"","items":[{"id":"text-1791983544994-40slmr","type":"CardText","text":"<h2><strong>Yes, we can. Our diverse fleet of distribution vehicles provides flexibility and ensures we can handle ambient, refrigerated, frozen and hazardous goods. Read more about our healthcare transport solutions.</strong></h2><p></p>"}]},{"id":"section-1791983545202-p7ooa0","type":"Section","label":"","title":"Can you meet my environmental concerns without compromising the quality or efficiency of my healthcare logistics delivery?","subtitle":"","items":[{"id":"text-1791983545202-sgjk37","type":"CardText","text":"<h2><strong>Our services meet global environmental transport objectives, and we adapt modalities to suit changing conditions and circumstances. For example, we can shift from airfreight to sea freight in order to cut carbon emissions and costs.</strong></h2><p></p>"}]},{"id":"section-1791983545426-ujhi5b","type":"Section","label":"","title":"Does ILS meet my need for dedicated healthcare warehouses?","subtitle":"","items":[{"id":"text-1791983545426-d4dyts","type":"CardText","text":"<h2><strong>Yes. Our specialised healthcare sites are secure and specially equipped for healthcare products. Certain locations also offer condition-controlled environments.</strong></h2><p></p>"}]},{"id":"section-1791983545658-97xk4f","type":"Section","label":"","title":"What healthcare logistics support do you offer?","subtitle":"","items":[{"id":"text-1791983545658-ou9n2h","type":"CardText","text":"<h2><strong>We support your supply chain by acting as 3PL, 3½PL or 4PL as required. Each specific role offers different models for distribution and supply chain collaboration. Our state-of-the-art freight management system sets the standard for healthcare distribution. We base our distribution solutions on your requirements, taking into account the needs of each of your customers. And we handle the entire process from planning through execution and administration</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'72a3f988-9c77-4d4d-a1a8-a8a93e41bff0')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'72a3f988-9c77-4d4d-a1a8-a8a93e41bff0', N'f77ee04a-e3d6-4973-b100-f3810817cbad', N'Industrial Logistics', 2, NULL, NULL, NULL, NULL, NULL, N'<p>Balancing service and cost</p>', N'{"version":1,"items":[{"id":"legacy-section-1791984351666","type":"Section","label":"About","title":"Industrial logistics","subtitle":"","items":[{"id":"legacy-text-1791984351666","type":"CardText","text":"<h2><strong>Our industrial logistics solutions give you the right balance between quality, cost, flexibility and standardisation. This lets you meet the challenges you face in a dynamic market that is often underpinned by regulatory demands.</strong></h2><h2><strong>We provide industry-specific solutions to a diverse range of sectors, including food ingredients and raw materials, machinery and components, packaged chemicals, construction, and the wholesale and manufacturing sectors. We operate industrial facilities specially equipped for storing hazardous goods, tyres, food ingredients and odd-sized equipment. Specific services to meet your industrial needs include repackaging, drum filling, hazardous goods labelling and transport management. For a number of our key customers we run in-house operations facilitating production processes for various logistics activities.</strong></h2><p></p>"}]},{"id":"section-1791984418188-yas4yq","type":"Section","label":"","title":"Food ingredients and raw materials","subtitle":"","items":[{"id":"text-1791984418188-x5gm8u","type":"CardText","text":"<h2><strong>Food ingredients can amount to 60% of the total costs for the process industry and raw materials up to 20% of costs for OEMs. The price volatility of these commodities varies depending on conditions. This is why improving supply chain transparency can help you manage this volatility and deliver short-term growth while achieving long-term competitive advantage.</strong></h2><p></p>"},{"id":"highlight-1791984470067-savqat","type":"HighlightText","text":"<h3><strong>Our global network ensures timely source flows to your production facilities. We can also manage warehousing and distribution activities so goods arrive in perfect condition with your end customers.</strong></h3><p></p>"},{"id":"highlight-1791984470227-wjq784","type":"HighlightText","text":"<h3><strong>Our warehousing and cross-dock facilities are equipped to meet relevant requirements and regulations (such as HACCP, AIB, SQAS, ISO, GMP and GDP) and our IT systems easily meet your requirements for track and trace, batch registration and/or expiry-date monitoring right down to individual item level to ensure the quality of your stock.</strong></h3><p></p>"},{"id":"highlight-1791984493267-65qety","type":"HighlightText","text":"<h3><strong>All of our processes are optimised to handle the high volumes and peaks in your supply chain.</strong></h3><p></p>"}]},{"id":"section-1791984418363-glf0rq","type":"Section","label":"","title":"Chemicals","subtitle":"","items":[{"id":"text-1791984418363-2fhupu","type":"CardText","text":"<p>Transport and logistics for chemicals requires expertise and full understanding of relevant Quality, Health &amp; Safety, and Environment requirements. Our ILS team of chemical logistics experts understands the complex legislative environment in which your chemicals business operates and can deliver the chemical logistics solutions you need.</p><p></p>"},{"id":"highlight-1791984534075-1jow9i","type":"HighlightText","text":"<h3><strong>ILS chemical transport and logistic solutions are fully flexible and designed to meet your needs for efficiency and safety. We offer safe and secure transport of chemicals using air, sea or road using our extensive network of suppliers. All suppliers are experienced in working with chemical shipments and have the required accreditation, licenses and insurance for chemical transportation.</strong></h3><p></p>"},{"id":"highlight-1791984534203-6m1j1z","type":"HighlightText","text":"<h3><strong>In addition to transport, we offer chemical warehousing facilities, product handling and packaging and on-site logistics services. All facilities comply with applicable safety regulations so you can have peace of mind that your chemicals are handled correctly at all times.</strong></h3><p></p>"}]},{"id":"section-1791984418555-lw5235","type":"Section","label":"","title":"Machinery and components","subtitle":"","items":[{"id":"text-1791984418555-d0hmaq","type":"CardText","text":"<h2><strong>The commoditisation of machines and components leaves manufacturers with ever thinning margins making it increasingly important to focus on product innovation, leading edge technology, cost containment and creation of high barriers to entry, while outsourcing the actual manufacturing and supply chain management.</strong></h2><p></p>"},{"id":"highlight-1791984647813-28drrj","type":"HighlightText","text":"<h3><strong>We maximise the amount of stock in transit, shifting the focus from warehouse management to supply chain execution. In addition, new concepts surrounding assembly at destination and bonded warehousing have decreased duty and tax exposure on capital intensive goods but have greatly increased the complexity of the supply chain.</strong></h3><p></p>"},{"id":"highlight-1791984647981-z3yduw","type":"HighlightText","text":"<h3></h3><h3><strong>Our industrial solutions offer an entire range of services including assembly/disassembly and special packaging / repackaging, warehousing, machine modifications prior to final delivery, freight management and ‘out of stock’ time-sensitive deliveries throughout the world.</strong></h3><h3></h3><p></p>"},{"id":"highlight-1791984650284-7fjl21","type":"HighlightText","text":"<h3><strong>Furthermore, our network of bonded warehouses will place you close to your customers, allowing you to better control your business.</strong></h3><p></p>"}]},{"id":"section-1791984418747-wpc8ry","type":"Section","label":"","title":"Industrial spare parts logistics","subtitle":"","items":[{"id":"text-1791984418747-rjx9u7","type":"CardText","text":"<h2><strong>Fast and reliable spare parts delivery is key to balancing minimum stock levels and avoiding downtime. Our highly efficient warehousing and distribution service allows late cut-off times with time definite, same-day or next-day deliveries to dealers, distributors or even on site.</strong></h2><h2><strong><br></strong></h2><p></p>"},{"id":"highlight-1791984689692-i7dzm3","type":"HighlightText","text":"<h2><strong>We manage numerous regional spare parts distribution centres across the world, and integrate and manage SLAs in the various parts of the spare parts chain.</strong></h2><h2></h2><p></p>"},{"id":"highlight-1791984689852-ujmb1s","type":"HighlightText","text":"<h2><strong>Importantly, we help you significantly reduce your spare parts inventory levels by increasing visibility through our company-wide WMS and FMS suite.</strong></h2><p></p>"}]},{"id":"section-1791984418955-5f7if8","type":"Section","label":"","title":"Warehouse automation","subtitle":"","items":[{"id":"text-1791984418955-2a8qxh","type":"CardText","text":"<h2><strong>If you work with substantial volumes, warehouse automation can offer significant benefits for your business. We can guide you through the process of analysing your situation, designing a tailor-made solution and implementing the turn-key system, either in your own dedicated facility or in our multi-user warehouse.</strong></h2><h2></h2><p></p>"},{"id":"highlight-1791984704788-8fud86","type":"HighlightText","text":"<h2><strong>In addition to extensive engineering and technical expertise, we also offer staff training and support for a smooth transition to the new automated process.</strong></h2><h2></h2><p></p>"},{"id":"highlight-1791984704931-1mcesl","type":"HighlightText","text":"<h2><strong>With warehouse automation in place, you can reduce labour costs, minimise product damages and get a return on investment while maintaining the necessary flexibility in the context of a 24-hour operation.</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'52b1ff64-8d01-4e74-81da-ab0d89b91fbc')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'52b1ff64-8d01-4e74-81da-ab0d89b91fbc', N'529dcb91-012c-4540-8b5b-fab02c242e69', N'Contact Us', 4, NULL, NULL, N'/contact', NULL, NULL, NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'd577cff1-0d9d-4f6a-affe-ad7086146762')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'd577cff1-0d9d-4f6a-affe-ad7086146762', N'3e0c0a0a-3471-4787-b956-7653fb76de7f', N'Dangerous Goods Labels', 2, NULL, NULL, NULL, NULL, NULL, N'<p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791985329620","type":"Section","label":"","title":"Classification of dangerous goods labels","subtitle":"","items":[{"id":"legacy-text-1791985329620","type":"CardText","text":"<p>–&nbsp;<strong>Dangerous goods</strong>&nbsp;are substances which because of their characteristics and composition may endanger the health and safety of persons and the environment. Compliance with a series of strict requirements for their storage, handling and transport is compulsory.</p><p>–&nbsp;<strong>Dangerous goods labels</strong>&nbsp;must be used in transport to identify the risks of the products being transported. Goods are classified according to the international regulation&nbsp;<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.boe.es/buscar/doc.php?id=BOE-A-2019-9661\"><u>ADR 2019 (European Agreement on the Transport of Dangerous Goods by Road)</u></a>&nbsp;based on their composition and degree of danger.</p>"},{"id":"highlight-1791985341228-rfrs6j","type":"HighlightText","text":"<ul><li><p>Class 1: Explosive substances and articles. All goods with a risk of causing an explosion, whether it is a mass explosion, a light fire, a blast wave, etc. Identified by a black icon or number on an orange background.</p></li><li><p>Class 2: Gases. Classified into three subdivisions according to whether they are flammable (flame icon on a red background), non-flammable non-toxic (cylinder icon on a green background) or toxic (skull icon on a white background).</p></li><li><p>Class 3: Flammable liquids. Materials with a maximum flash point of 60º C.</p></li><li><p>Class 4: Flammable solids and other solid explosive substances. Subdivided into solid flammable goods (4.1 white and red striped background), self-reactive substance (4.2 white/red background) and substances that release flammable gases in contact with water (4.3 blue background).</p></li><li><p>Class 5: Oxidising substances and organic peroxides. Identified by the yellow background.</p></li><li><p>Class 6: Toxic substances (which can be harmful to health and even fatal) or infectious substances (which contain micro-organisms such as bacteria or viruses). The label has a white background.</p></li><li><p>Class 7: Radioactive substances. The label has a white or yellow/white background depending on the level of radioactivity of the goods.</p></li><li><p>Class 8: Corrosive substances. Icon with two pipettes on a black and white background with the word “Corrosive”.</p></li><li><p>Class 9: Miscellaneous dangerous substances. The label has black and white stripes at the top, with a white background on the bottom.</p></li></ul><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'f0e0362c-a9b0-41b2-ae3a-b2c2838dd10e')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'f0e0362c-a9b0-41b2-ae3a-b2c2838dd10e', N'3e0c0a0a-3471-4787-b956-7653fb76de7f', N'Customs Duties Calculator', 4, NULL, NULL, N'/customs-duties-calculator', NULL, NULL, NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'e415cd5e-af84-4601-9877-bed7206545ea')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'e415cd5e-af84-4601-9877-bed7206545ea', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Cargo Insurance', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>Enjoy peace of mind and work with ILS on your insurance for transport and logistics</strong></h2><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791981771683","type":"Section","label":"IT''S YOUR BUSINESS","title":"MAKE SURE IT''S PROTECTED","subtitle":"","items":[{"id":"legacy-text-1791981771683","type":"CardText","text":"<h2><strong>Get tailored logistics insurance coverage matching your exact needs and peace of mind knowing that your goods are protected against unpredictable events.</strong></h2><h2><strong>We take the utmost care of your goods. Regardless, various unavoidable perils and accidents can cause damage and expose your goods to risks. Whether you ship by sea, air or road or store goods in warehouses, having your goods and shipments insured are crucial to protect your business.&nbsp;</strong></h2><h2><strong>Our logistics insurance solution allows you to secure your business in case of unexpected circumstances. De-risk your supply chain with Cargo insurance&nbsp;coverage&nbsp;and let ILS tailor the transport and logistics insurance to your needs.</strong></h2><p></p>"}]},{"id":"section-1791981942547-tulozh","type":"Section","label":"COVER ","title":"YOUR GOODS AND SHIPMENTS","subtitle":"","items":[{"id":"text-1791981942547-2ahjj2","type":"CardText","text":"<h2><strong>You never know what can happen when your goods are transported by sea, air, or road. Unforeseen circumstances can impact your business in a split second.</strong></h2><h2><strong>&nbsp;Laws and international conventions dictate that your freight forwarder has only limited liability. So, it''s up to you to insure the unforeseen. With the ILS Cargo Insurance, you can easily transfer the risk from you to us - and stay in business.</strong></h2><h2><strong>&nbsp;We offer comprehensive coverage options that allow you to protect your business against unexpected circumstances, quick and hassle-free.</strong></h2><p></p>"}]},{"id":"section-1791981942738-wy7l5w","type":"Section","label":"MANAGE ","title":"THE UNFORESEEN","subtitle":"","items":[{"id":"text-1791981942738-f3o5rq","type":"CardText","text":"<h2><strong>Incidents happen when goods are transported. Unavoidable perils, hazards, accidents, or even human error often cause damage.</strong></h2><h2><strong>ILS Cargo Insurance will protect your potential loss in case the unforeseen happens while your goods are in transit.</strong></h2><p></p>"}]},{"id":"section-1791981942922-8r50gu","type":"Section","label":"SAFEGUARD ","title":"YOUR BUSINESS","subtitle":"","items":[{"id":"text-1791981942922-a2xkzt","type":"CardText","text":"<h2><strong>National and international laws and conventions limit a freight forwarder''s liability. Entitling you to relatively small compensation.</strong></h2><h2><strong>With freight insurance, you will be fully compensated in case of damage, theft, or loss in relation to the value for which the item is insured. Safeguarding your business.</strong></h2><p></p>"}]},{"id":"section-1791981943106-p1ksnm","type":"Section","label":"SIMPLIFY ","title":"THE PROCESS","subtitle":"","items":[{"id":"text-1791981943106-rsr4zt","type":"CardText","text":"<h2><strong>Getting the right cargo insurance shouldn''t be difficult. With ILS, you receive tailored shipping insurance that matches your needs.</strong></h2><h2><strong>Fast claims handling, no deductible, and all-risk coverage ensure the protection of goods in the event of loss or damage.</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'dfd4f635-bae5-4956-97e6-bfd7d6bad26a')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'dfd4f635-bae5-4956-97e6-bfd7d6bad26a', N'cf95a2fd-257b-4905-9e78-2c0049865442', N'Join Our Team', 4, NULL, NULL, N'/recruitment', NULL, NULL, NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'a4bf805e-5f24-46c9-b6cc-c22409fa160d')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'a4bf805e-5f24-46c9-b6cc-c22409fa160d', N'3e0c0a0a-3471-4787-b956-7653fb76de7f', N'Incoterms', 2, NULL, NULL, NULL, NULL, NULL, NULL, N'{"version":1,"items":[{"id":"legacy-section-1791985238820","type":"Section","label":"","title":"Types of Incoterms (Incoterms 2020)","subtitle":"","items":[{"id":"legacy-text-1791985238820","type":"CardText","text":"<p><strong>For Any Mode of Transport (7 Terms)</strong>:</p><p></p>"},{"id":"highlight-1791985264629-kl9eer","type":"HighlightText","text":"<p></p><ul><li><p><strong>EXW</strong>&nbsp;(Ex Works): Seller makes goods available at their premises. Buyer takes all risk and cost from there.</p></li><li><p><strong>FCA</strong>&nbsp;(Free Carrier): Seller delivers to carrier nominated by buyer; risk transfers at delivery.</p></li><li><p><strong>CPT</strong>&nbsp;(Carriage Paid To): Seller pays freight to destination, but risk transfers when delivered to the first carrier.</p></li><li><p><strong>CIP</strong>&nbsp;(Carriage and Insurance Paid To): Like CPT, but seller also provides insurance for buyer''s risk.</p></li><li><p><strong>DAP</strong>&nbsp;(Delivered at Place): Seller delivers goods ready for unloading at named place.</p></li><li><p><strong>DPU</strong>&nbsp;(Delivered at Place Unloaded): Seller delivers and unloads at named place.</p></li><li><p><strong>DDP</strong>&nbsp;(Delivered Duty Paid): Seller handles all costs and risks, including import duties, to the final destination.</p></li><li><p><strong>For Sea &amp; Inland Waterways Only (4 Terms)</strong>:</p></li><li><p><strong>FAS</strong>&nbsp;(Free Alongside Ship): Risk &amp; cost transfer when goods are placed alongside the vessel.</p></li><li><p><strong>FOB</strong>&nbsp;(Free On Board): Risk &amp; cost transfer when goods are loaded&nbsp;<em>on board</em>&nbsp;the vessel.</p></li><li><p><strong>CFR</strong>&nbsp;(Cost and Freight): Seller pays freight to destination port; risk transfers at loading.</p></li><li><p><strong>CIF</strong>&nbsp;(Cost, Insurance, and Freight): Like CFR, but seller also arranges minimum insurance.&nbsp;</p></li></ul><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'1e5a9a58-e470-4da2-93fb-c2ccc296dc90')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'1e5a9a58-e470-4da2-93fb-c2ccc296dc90', N'cc99c0e8-2139-4d75-9a51-25623a5799e6', N'Philosophy ', 2, NULL, NULL, NULL, NULL, NULL, N'<p>Great networks enable you to achieve your goals effectively and technology allows you to do so efficiently.</p>', N'{"version":1,"items":[{"id":"section-1792002325731-kve5mt","type":"Section","label":"","title":"At ILS, our philosophy is to optimally connect","subtitle":"","items":[{"id":"text-1792002325732-16oh2q","type":"CardText","text":"<p><strong>⦁ Production and sales</strong></p><p><strong>⦁ Manufacturer and consumer interests</strong></p><p><strong>⦁ Industry and retail sectors</strong></p>"},{"id":"closing-1792002382708-d4a98d","type":"ClosingText","text":"<p><strong>You can always be one step ahead of the market, using our customized in-house platform which consolidates our services and industry expertise under one umbrella. Creative thinking and professional performance - This is our guiding principle at ILS as we move</strong></p><p><strong>through the new generation of the Freight Forwarders. Our goal is to think ahead and actively shape the future through innovation, efficiency and customized logistics solutions. We seek to achieve speed, endurance and to overcome vast distances as a result of thorough preparations.</strong></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'babe6f7a-9e58-4a9c-b5ae-cf0736d9082e')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'babe6f7a-9e58-4a9c-b5ae-cf0736d9082e', N'f77ee04a-e3d6-4973-b100-f3810817cbad', N'Retail Logistics', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>Our agile solutions connect e-commerce and physical retail</strong></h2><p></p>', N'{"version":1,"items":[{"id":"page-highlights-highlight-1791984794444-0btrcz","type":"PageHighlights","items":[{"id":"highlight-1791984794444-0btrcz","type":"HighlightText","text":"<h2><strong>Order management, multichannel fulfilment, white glove delivery and reverse logistics – we offer many retail shipping, transport and logistics solutions tailored for the retail industry.</strong></h2><p></p>"}]},{"id":"legacy-section-1791984746020","type":"Section","label":"About","title":"Retail Logistics","subtitle":"","items":[{"id":"legacy-text-1791984746020","type":"CardText","text":"<h2><strong>Logistics for the retailing and fashion industries need to be highly flexible as rapid growth and exponential change are the standard, not the exception. Managing logistics in fashion markets requires supply chains that are increasingly reactive with technology that can help teams make decisions on urgent demand. Goods that sell steadily throughout the year need different models of supply chain than seasonal items with short shelf lives.</strong></h2><p></p>"}]},{"id":"section-1791984871132-v5pvc5","type":"Section","label":"","title":"What does ILS offer the consumer, retailers and the fashion industry as a retail logistics provider?","subtitle":"","items":[{"id":"text-1791984871133-7zd3nf","type":"CardText","text":"<h2><strong>Our integrated services and technological capabilities help you to be more productive and efficient with agile supply chain solutions that are fully tailored to your requirements and expectations, and those of your customers.</strong>sumption areas.</h2><p></p>"}]},{"id":"section-1791984901652-xry4j5","type":"Section","label":"","title":"How can you meet my customers'' different needs?","subtitle":"","items":[{"id":"text-1791984901652-fk5sgx","type":"CardText","text":"<h2><strong>Our best-in-class supply chain solutions provide a full range of superior services, including order management, lead logistics solutions, and contract logistics solutions, such as fiscal representation, customs support and a wide variety of value-added services. Whatever your requirements, we can tailor the exact solution you need.</strong></h2><p></p>"}]},{"id":"section-1791984901795-gfbvv5","type":"Section","label":"","title":"Can you integrate your technology with mine?","subtitle":"","items":[{"id":"text-1791984901795-dhei2n","type":"CardText","text":"<h2><strong>We can integrate our IT systems with your end-to-end order fulfilment systems providing order, item and SKU level visibility. We also offer integration of your e-commerce platform and the systems of your main freight forwarders to provide your customers with real-time inventory data, order status details and track and trace information. Learn more about ils Connectivity.</strong></h2><p></p>"}]},{"id":"section-1791984951043-8ghmmr","type":"Section","label":"","title":"Our retail logistics services include","subtitle":"","items":[{"id":"text-1791984951043-2udjxt","type":"CardText","text":"<p></p>"},{"id":"highlight-1791984978484-suymnp","type":"HighlightText","text":"<h2><strong>Consumer goods</strong></h2><h2><strong><em>Global sourcing and production with strict on-time deliveries require a global network able to be agile and act fast on the needs of FMCG companies. No matter if it is visibility and optimisation of global air or ocean freight or urgent need of warehouse space and solutions, we are ready to innovate and execute.</em></strong></h2><p></p>"},{"id":"highlight-1791984978660-2073l5","type":"HighlightText","text":"<h2><strong>Sports and leisure</strong></h2><h3><strong><em>Winning is everything, and our operations deliver consistent performance all year round. Our value-added services range from sophisticated Lead Logistics and 4PL solutions to order management and flow optimisation. Our contract logistics solutions include quality inspection, price tagging, packaging up to your specific product assemblies, and kitting to provide that extra edge to get your sports and leisure wear over the line first.</em></strong></h3><p></p>"},{"id":"highlight-1791984978836-ohpdx6","type":"HighlightText","text":"<h2><strong>Consumer electronics</strong></h2><h3><strong><em>We know being out of stock can mean out of a sale. Our supply chain is geared to making sure a customer leaves with the product he or she wants. New product launches, reverse logistics and timely deliveries are our stock in trade. Our extensive global network ensures inbound freight capacity is delivered at scheduled times, and the economies of scale offered by our TAPA-A distribution centres minimise the logistics burden on your margins.</em></strong></h3><p></p>"},{"id":"highlight-1791984979092-wnvsu5","type":"HighlightText","text":"<h2><strong>Home improvement / DIY</strong></h2><h3><strong><em>The home improvement and DIY markets are growing in developing markets, and our global network can get your products into homes in the most out-of-the-way places. And we deliver the quality and flexibility retailers want. Our services include packaging or re-packaging, palletising or re-palletising, labelling or re-labelling and kitting. We manage waste, returns, stock levels and co-packing programmes.</em></strong>r</h3><p></p>"},{"id":"highlight-1791984982316-u84h3k","type":"HighlightText","text":"<h2><strong>Fashion</strong></h2><h3><strong><em>\"In with the new and out with the old\" sums up today''s world of fast fashion. Ever-shorter product life cycles, the lure of global brands, the rise of social media and multiple distribution channels demand a market-responsive and agile supply chain solution for the fashion industry. Our end-to-end order management services combined with effective consolidation of shipments allow on-time delivery without compromising cost. We support coordination of your suppliers stretching from vendor management programs to running efficient and effective distribution centres on your behalf, so your supply chain creates the required competitive advantage.</em></strong></h3><p></p>"},{"id":"highlight-1791984983044-1v8q9g","type":"HighlightText","text":"<h2><strong>Personal care</strong></h2><h3><strong><em>Our green and sustainable principles are embedded in the way we work and our supply chain mirrors your commitment as manufacturers of personal care products to sustainable sourcing, production and packaging.</em></strong></h3><p></p>"},{"id":"highlight-1791984983372-r1p7w7","type":"HighlightText","text":"<h2><strong>Luxury goods and high fashion</strong></h2><h3><strong><em>We combine origin logistics, close to sourcing and act as your white glove agent on an end-to-end basis for luxury goods and supply chains. Combining effective origin logistics with destination logistics allows visibility throughout the supply chain and fast replenishment in major consumption areas.</em></strong></h3><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'57e4d0f0-7333-4d44-8c48-d1939cee610e')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'57e4d0f0-7333-4d44-8c48-d1939cee610e', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'A shared vision, strong coordination, and trusted expertise', 3, N'<p>The collaboration between ILS Egypt and <a target="_blank" rel="noreferrer" class="font-semibold text-sky-600 underline decoration-sky-300 underline-offset-4 transition hover:text-sky-500" href="https://www.linkedin.com/company/gmcc-welling/"><strong>GMCC&amp;Welling</strong></a> reflects our commitment to building reliable logistics partnerships that support global operations and long-term growth.</p><p><br></p>', N'/uploads/content/00d84afc84d94003a47f00522b4a6bf0.webp', NULL, N'Ils News', CAST(N'2025-11-06T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'b91ce136-e934-4970-8ff5-d605d7e529d4')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'b91ce136-e934-4970-8ff5-d605d7e529d4', N'cc99c0e8-2139-4d75-9a51-25623a5799e6', N'Certificates', 2, NULL, NULL, NULL, NULL, NULL, NULL, N'{"version":1,"items":[{"id":"legacy-section-1792002856229","type":"Section","label":"","title":"Our memberships and certifications reflect ILS Egypt’s commitment to professional standards and global logistics networks.","subtitle":"","items":[{"id":"legacy-text-1792002856229","type":"CardText","text":"<pre><code>\n</code></pre><img src=\"http://localhost:5250/uploads/content/e1f71a7658334bb197d7d0a83b91c51c.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code>\n\n</code></pre><pre><code>\n</code></pre><img src=\"http://localhost:5250/uploads/content/4062c0a3532543e98e7700d8544558d1.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code>\n</code></pre><img src=\"http://localhost:5250/uploads/content/29045d29965944bd9594e600623be351.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code></code></pre><img src=\"http://localhost:5250/uploads/content/5a03ddf97c8c47548227e56b54f26089.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code>\n</code></pre><img src=\"http://localhost:5250/uploads/content/503c132bcd7145ab9bc782a6150b8df9.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code>\n</code></pre><img src=\"http://localhost:5250/uploads/content/dc927d4edd9440e6a0a790993dd1ac14.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code>\n</code></pre><img src=\"http://localhost:5250/uploads/content/eeb8e2712b7f4bde8e0e13a5e0ab00e3.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code></code></pre><img src=\"http://localhost:5250/uploads/content/f88eb6c0f275406d89f1fa55fb87ff24.webp\" data-image-align=\"left\" data-image-width=\"auto\" data-image-height=\"auto\" data-image-max-height=\"\" data-image-spacing=\"0px\" data-image-layout=\"above\" style=\"display: block; width: auto; max-width: none; height: auto; object-fit: fill; margin: 0px auto 0px 0px; max-height: none; border-radius: 12px;\"><pre><code></code></pre><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'7e3618cc-7953-4de5-b047-d6cec65d759c')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'7e3618cc-7953-4de5-b047-d6cec65d759c', N'f77ee04a-e3d6-4973-b100-f3810817cbad', N'Energy', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>Renewable energy logistics Solutions for cleaner, greener energy</strong></h2><p></p>', N'{"version":1,"items":[{"id":"legacy-section-1791984095827","type":"Section","label":"About","title":"Energy","subtitle":"","items":[{"id":"legacy-text-1791984095827","type":"CardText","text":"<h2><strong>Renewable energy is vital for diversifying our energy supply and reducing dependence on polluting fossil fuels. We ensure you get innovative, reliable and tailored solutions for your renewable energy transport logistics – no matter how harsh your environment, or how remote your location.</strong></h2><h2><strong> climate change. Find out more about how we work with sustainability.</strong></h2><p></p>"},{"id":"highlight-1791984152763-c8zyqu","type":"HighlightText","text":"<h3><strong>We are a world-leader in energy logistics with expertise in the development and delivery of safe and economic transport solutions for the wind and solar energy industries. Our services range from transport of large out of gauge wind turbine components to planning the logistics for an entire solar farm. </strong></h3><p></p>"}]},{"id":"page-highlights-highlight-1791984173058-yf8hlh","type":"PageHighlights","items":[{"id":"highlight-1791984173058-yf8hlh","type":"HighlightText","text":"<h2><strong>Our experts can help you with:</strong></h2><p></p>"}]},{"id":"page-closings-closing-1791984173818-l1lq0y","type":"PageClosings","items":[{"id":"closing-1791984173818-l1lq0y","type":"ClosingText","text":"<ul><li><p><strong><em>Planning, execution and monitoring</em></strong></p></li><li><p><strong><em>Air, sea, road or intermodal freight services</em></strong></p></li><li><p><strong><em>Dedicated heavy-lift engineers</em></strong></p></li><li><p><strong><em>Oversize transport</em></strong></p></li><li><p><strong><em>Out of gauge installations</em></strong></p></li><li><p><strong><em>Marine and cargo charters, as well as port agency and husbandry services</em></strong></p></li><li><p><strong><em>Charter and Emergency Services covering all global regions and time zones 24/7/365</em></strong></p></li><li><p><strong><em>Expertise in regulatory compliance</em></strong></p></li><li><p><strong><em>Contract bid assistance</em></strong></p></li></ul><p></p>"}]},{"id":"section-1791984174666-yyhb65","type":"Section","label":"","title":"The experience you need","subtitle":"","items":[{"id":"text-1791984174666-m63v9l","type":"CardText","text":"<h2><strong>We have been involved in the alternative energy industry for more than 20 years. This expertise means we understand the challenges you face and have the renewable energy logistics solutions you need.</strong></h2><h2><strong>From source to site, under challenging conditions and across difficult terrains, you can rely on us to understand the unique requirements of each task. With this understanding, we can plan and configure solutions for solar and wind energy transport and logistics that deliver maximum benefits to you.</strong></h2><p></p>"}]},{"id":"section-1791984274082-gwqzl1","type":"Section","label":"","title":"Quality, Health, Safety, Environment","subtitle":"","items":[{"id":"text-1791984274082-yi86d0","type":"CardText","text":"<h2><strong>Our QHSE quality assurance system is our commitment to supplying the service and quality you require. As well as reducing the risks to people, shipments and surroundings, our investment in QHSE motivates our people to drive improvements and increase productivity.</strong></h2><p></p>"}]},{"id":"section-1791984274523-kw1wg8","type":"Section","label":"","title":"For a more sustainable way forward","subtitle":"","items":[{"id":"text-1791984274523-foi77z","type":"CardText","text":"<h2><strong>ILS is firmly committed to supporting the transition to greener, more environmentally-friendly practices in transport and logistics. We offer a range of Green Logistics solutions, ranging from CO2 reporting to strategic supply chain optimisation and sustainable fuel offerings. With Green Logistics solutions you can introduce greater sustainability into your operations and reduce the impact of transport and logistics on climate change. Find out more about how we work with sustainability.</strong></h2><h2></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'b0efd680-d2c6-4635-995c-dad02e8e4aa9')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'b0efd680-d2c6-4635-995c-dad02e8e4aa9', N'3e0c0a0a-3471-4787-b956-7653fb76de7f', N'Nafeza Platform', 4, NULL, NULL, N'https://www.nafeza.gov.eg/en', NULL, NULL, NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'73311390-5e27-46d8-bf8d-e76e9982f9ce')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'73311390-5e27-46d8-bf8d-e76e9982f9ce', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'ILS Projects Transport', 2, NULL, NULL, NULL, NULL, NULL, N'<p>When you need to move heavy, oversized or complex cargo, we can help</p>', N'{"version":1,"items":[{"id":"legacy-section-1791982078915","type":"Section","label":"PROJECT LOGISTICS FOR ","title":"MAJOR MOVES ANYWHERE IN THE WORLD","subtitle":"","items":[{"id":"legacy-text-1791982078915","type":"CardText","text":"<h2><strong>Our project transport services offer reliable and cost-effective solutions that meet high standards of safety, service and quality. When you need to move heavy, oversized or complex cargo, ILS’s Project Transport is ready to provide specialized, tailor-made solutions for the most ambitious energy, industrial and capital infrastructure projects. With a global force of skilled professionals and decades of experience in this area, we are ready to serve your most complex logistics demands and execute any major move, even to the most remote locations. Our experts have the necessary knowledge, track record and resources to create end-to-end transport solutions for each phase of the entire lifecycle of energy projects – whether it’s moving wind turbines or solar panels in the renewable energy sector, or supporting oil and gas projects from exploration to decommissioning.</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'fcf2450e-22db-4d1f-bbae-ed70c4381c0c')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'fcf2450e-22db-4d1f-bbae-ed70c4381c0c', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Sea Freight', 2, NULL, NULL, NULL, NULL, NULL, N'<h2><strong>When cost matters and time is not an issue</strong></h2><p></p>', N'{"version":1,"items":[{"id":"section-1791967253756-81yy4c","type":"Section","label":"","title":"ILS''s SEA FREIGHT SERVICES SUPPORT ","subtitle":"YOUR NEEDS FOR OPTIMIZED, SECURE AND FLEXIBLE SOLUTIONS ","items":[{"id":"text-1791967253756-rnpwu1","type":"CardText","text":"<h2><strong>With the enormous volumes of freight that we ship and the multitude of carriers we work with, we can offer you frequent departures and the capacity you need – to and from every major port in the world. Whether your needs are complex or straightforward and whatever your goods, we can help you with you with end-to-end solutions across transport modes whether it be by sea, air, road, or rail.</strong></h2><p></p>"}]},{"id":"section-1791982312506-m7wbeu","type":"Section","label":"","title":"LOCAL KNOWLEDGE OF LOCAL CONDITIONS","subtitle":"","items":[{"id":"text-1791982312506-jq6gmw","type":"CardText","text":"<h2><strong>In every major port, we have experienced employees with detailed knowledge of local and international export and import compliance. Our staff can assist you in understanding each country’s requirements, as well as local pickup and last mile delivery. And if you need logistics support or warehouse management for your supply chain, we can handle that too.</strong></h2><p></p>"}]},{"id":"section-1791982312681-ui94t5","type":"Section","label":"","title":"OUR SEA FREIGHT SERVICES INCLUDE","subtitle":"","items":[{"id":"text-1791982312681-ujp0c4","type":"CardText","text":"<ul><li><p><strong>Full container load</strong></p></li><li><p><strong>Less than container load</strong></p></li><li><p><strong>Non-containerized load</strong></p></li><li><p><strong>Buyer''s consolidation services</strong></p></li><li><p><strong>Break bulk</strong></p></li></ul><p></p>"}]},{"id":"section-1791982312897-suh2hj","type":"Section","label":"","title":"SEA FREIGHT COMPLIANCE","subtitle":"","items":[{"id":"text-1791982312897-r3ra5x","type":"CardText","text":"<h2><strong>Moving cargo from A to B across the world''s seas can be challenging. Transport documents, regulations, country-specific compliance, local requirements and customs clearance are just some of the steps to be considered before your cargo can be dispatched to its final destination. Proper export documentation and import licenses and requirements are becoming increasingly important factors when transporting cargo. With years of experience in cargo shipment, our staff can support you in delivering your sea freight in full compliance with all requirements.</strong></h2><p></p>"}]},{"id":"section-1791982313089-ep8qn7","type":"Section","label":"","title":"A NETWORK OF TRUSTED SEA FREIGHT CARRIERS","subtitle":"","items":[{"id":"text-1791982313089-008lcu","type":"CardText","text":"<h2><strong>When you need the price advantage of sea freight, our agreements with all the major global and regional sea freight carriers will mean we can get you the best competitive combination of routing, carrier, price and departure and arrival times to suit your needs. You get the flexibility to ship your cargo when it suits you best.</strong></h2><p></p>"}]},{"id":"page-closings-closing-1791982313641-3p9tdz","type":"PageClosings","items":[{"id":"closing-1791982313641-3p9tdz","type":"ClosingText","text":"<h2><strong>Contact us today to discuss your requirements and we will find you the best and most reliable carrier for your cargo.</strong></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'279db350-885e-41ad-b933-f6605c343dae')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'279db350-885e-41ad-b933-f6605c343dae', N'3b4cc9d7-c706-4f5f-9c93-1dac8ba1b3ee', N'Warehousing and Distribution', 2, NULL, NULL, NULL, NULL, NULL, N'<p>Complete control and overview of your shipments</p>', N'{"version":1,"items":[{"id":"legacy-section-1791982602353","type":"Section","label":"About","title":"Warehousing and distribution","subtitle":"","items":[{"id":"legacy-text-1791982602354","type":"CardText","text":"<h2><strong>We offer more than just shipping services. We also offer packing and storage, receiving, and warehousing solutions to assist and support your business. Our services go further to Improve the performance of your supply chain by working with us to create a customized solution for your business.</strong></h2><p></p>"},{"id":"highlight-1791982671994-mn0yup","type":"HighlightText","text":"<h3><strong>Our warehousing professionals receive inventory and fulfill important product shipments or orders on a one-time or recurring basis. In addition, we will warehouse items for the short and long-term and provide you with regular status reports. Utilizing for inventory, kitting, packaging, and shipping of your stored items at the same location will reduce costs and allow for improved supply chain management. Rely on ILS Egypt for all of your packing, shipping, storage, and warehousing needs.</strong></h3><p></p>"}]},{"id":"section-1791982668738-n3m38l","type":"Section","label":"","title":"WAREHOUSING AND DISTRIBUTION SERVICES","subtitle":"","items":[{"id":"text-1791982668738-wytzys","type":"CardText","text":"<ul><li><p><strong>Loading and unloading</strong></p></li><li><p><strong>Palatalizing</strong></p></li><li><p><strong>Consolidation</strong></p></li><li><p><strong>Labeling</strong></p></li><li><p><strong>Packing and Re-packing</strong></p></li><li><p><strong>Packaging</strong></p></li></ul><p></p>"}]},{"id":"section-1791982668889-e9io7s","type":"Section","label":"","title":"WAREHOUSES TYPES","subtitle":"","items":[{"id":"text-1791982668889-6nshze","type":"CardText","text":"<ul><li><p><strong>Danger goods</strong></p></li><li><p><strong>General goods</strong></p></li><li><p><strong>Reefer goods</strong></p></li><li><p><strong>Bonded warehouses</strong></p></li><li><p><strong>Inbounded warehouses</strong></p></li></ul><h2></h2><p></p>"}]}]}');

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'9836cad1-a01b-4c31-8f4a-fb4ce8f1d626')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'9836cad1-a01b-4c31-8f4a-fb4ce8f1d626', N'47113a6b-87bc-4173-bea9-b4a692d32799', N'Exclusive Partnership and Deep Cooperation Announcement', 3, N'<p><strong>Exclusive Partnership and Deep Cooperation Announcement</strong></p><p>ILS Egypt and Grand Freight Service China are thrilled to announce their strategic cooperation as exclusive inter- agency cooperation</p><p>The exclusive collaboration between ILS Egypt and Grand Freight Service China will create seamless connections between Egypt and China, facilitating efficient trade and cargo movement, both companies will leverage their collective knowledge and experience to optimize supply chains, reduce costs, and enhance overall efficiency.</p><p>So, our customers can expect a comprehensive range of logistics services, including air freight, ocean freight, road transportation, and customs brokerage.</p><p>We look forward to a successful collaboration and the opportunity to serve our clients with enhanced capabilities and superior service.</p><p><strong>Deep Cooperation——GFS&amp;ILS</strong></p><p>为促进埃及业务的发展</p><p>GFS深圳鹏远在与埃及ILS协商后</p><p>决定与其深度合作</p><p>共同推进中国到埃及的进出口业务</p><p>进一步提升我们的服务质量</p><p>欢迎咨询合作</p>', N'/uploads/content/0568b8ff847840388a21b63dca8cb6fc.webp', NULL, N'Ils News', CAST(N'2025-11-23T00:00:00.0000000' AS DateTime2), NULL, NULL);

IF NOT EXISTS (SELECT 1 FROM dbo.Contents WHERE Id = N'32f069c1-3337-4457-a707-fdfe85c7d605')
    INSERT [dbo].[Contents] ([Id], [ParentId], [Title], [Type], [Body], [FeaturedImage], [LinkUrl], [Category], [PublishedAt], [PageIntroText], [PageContentOrder]) VALUES (N'32f069c1-3337-4457-a707-fdfe85c7d605', N'cc99c0e8-2139-4d75-9a51-25623a5799e6', N'Purpose and Strategy', 2, NULL, NULL, NULL, NULL, NULL, N'<p>Keeping supply chains flowing in a world of change.<br></p>', N'{"version":1,"items":[{"id":"legacy-section-1791978558992","type":"Section","label":"","title":"At ILS – Global Transport and Logistics","subtitle":"","items":[{"id":"text-1791986767053-t48uhp","type":"CardText","text":"<h2>we provide and manage supply chain solutions for thousands of companies every day – from the small family run business to the large global corporation. Our reach is global, yet our presence is local and close to our customers. All employees in more than 80 countries work passionately to deliver great customer experiences and high-quality services. We believe world trade drives world prosperity, but seamless trade is not a given.</h2><p></p>"},{"id":"highlight-1791986830605-nim8k7","type":"HighlightText","text":"<h2><strong>Our purpose</strong></h2><h2>Keeping supply chains flowing in a world of change</h2><p>We acknowledge our role as part of the critical infrastructure driving world trade and as a key enabler for the sustainable growth of all our stakeholders, including customers, shareholders and societies at large.</p><p>We conduct our business with integrity, respecting different cultures and the dignity and rights of individuals. We believe in contributing our fair share to the societies and local communities in which we operate while reducing the environmental footprint from our operations.</p><p>We take advantage of technology and digitalization. Our workflows are highly digitalized and our IT systems are integrated with both customers and suppliers. In a world of change, this enables us to continuously optimize our customers’ supply chains and supports efficient workflows for our employees.</p>"},{"id":"highlight-1791986831069-hvk2e6","type":"HighlightText","text":"<h2><strong>Our vision</strong></h2><h2>Sustainable growth</h2><p>We help our customers grow by keeping their supply chains flowing. We create efficient solutions for all businesses with focus on reliability, environmental impact and cost – regardless of industry and size.</p><p>We provide equal growth opportunities for all employees. People drive the success of our company, so the more we provide healthy and safe workplaces – as well as strong growth opportunities – the greater is our chance of achieving our ambitious growth targets.</p><p>We help societies grow. We conduct our business with integrity, respecting different cultures and the dignity and rights of individuals in all countries. We grow shareholder value. We want to continue to be a leading global supplier, fulfilling the customer needs for transport and logistics services. We target extensive growth - organic and through acquisitions - and aim to be among the most profitable in our industry.</p>"},{"id":"highlight-1791986831405-8dgs84","type":"HighlightText","text":"<h2>Our mission</h2><h2>Operational excellence</h2><p>World trade drives world prosperity, but seamless trade is not a given.</p><p>Through our persistent focus on transparency, productivity and scalability, we create more efficient global trade flows for all business.</p><p>We design our infrastructure – physical and digital – to support high service levels and efficient workflows.</p><p>Operational excellence goes hand in hand with sustainability. A well-planned supply chain is also a greener supply chain.</p><p>We are forwarders. People who get things done. We take ownership and show initiative. We always seek to find the better and rational solutions to the challenges we face.</p>"}]}]}');


